package com.rentrix.rentrixserver.common.id;

import java.security.SecureRandom;
import java.time.Instant;

/**
 * Internal 64-bit primary keys generated by the API (D-12, D-80).
 * <p>
 * Layout (63 bits, always positive): 41 bits of milliseconds since 2026-01-01T00:00Z
 * (good until 2095), 10 bits of node id, 12 bits of sequence. The sequence starts at a
 * random value each millisecond, so two instances that happen to pick the same node id
 * still rarely collide. Set {@code ID_NODE} (0–1023) per instance to rule collisions out.
 * <p>
 * Generating ids in the API keeps the DDL identical on SQLite, MySQL and PostgreSQL (no
 * AUTO_INCREMENT / IDENTITY) and needs no database round trip, which matters on SQLite's
 * single writer.
 */
public final class TimeOrderedIds {
	
	static final long EPOCH_MILLIS = Instant.parse("2026-01-01T00:00:00Z").toEpochMilli();
	static final int NODE_BITS = 10;
	static final int SEQUENCE_BITS = 12;
	static final long MAX_NODE = (1L << NODE_BITS) - 1;
	static final long SEQUENCE_MASK = (1L << SEQUENCE_BITS) - 1;
	
	private static final SecureRandom RANDOM = new SecureRandom();
	private static final TimeOrderedIds INSTANCE = new TimeOrderedIds(nodeFromEnv(System.getenv("ID_NODE")));
	
	private final long node;
	private long lastMillis = -1;
	private long sequenceStart;
	private long sequence;
	
	TimeOrderedIds(long node) {
		if (node < 0 || node > MAX_NODE) {
			throw new IllegalArgumentException("ID_NODE must be between 0 and " + MAX_NODE);
		}
		this.node = node;
	}
	
	/** Next id from the process-wide generator. */
	public static long next() {
		return INSTANCE.nextId();
	}
	
	static long nodeFromEnv(String value) {
		if (value == null || value.isBlank()) {
			return RANDOM.nextInt((int) MAX_NODE + 1);
		}
		return Long.parseLong(value.trim());
	}
	
	synchronized long nextId() {
		long now = Math.max(System.currentTimeMillis(), lastMillis); // never step back with the clock
		if (now != lastMillis) {
			lastMillis = now;
			sequenceStart = RANDOM.nextInt((int) SEQUENCE_MASK + 1);
			sequence = sequenceStart;
		} else {
			sequence = (sequence + 1) & SEQUENCE_MASK;
			if (sequence == sequenceStart) {
				// 4096 ids used in this millisecond: wait for the next one
				while (now <= lastMillis) {
					Thread.onSpinWait();
					now = System.currentTimeMillis();
				}
				lastMillis = now;
				sequenceStart = RANDOM.nextInt((int) SEQUENCE_MASK + 1);
				sequence = sequenceStart;
			}
		}
		return ((lastMillis - EPOCH_MILLIS) << (NODE_BITS + SEQUENCE_BITS)) | (node << SEQUENCE_BITS) | sequence;
	}
	
}
